  "lesson": "Channel and conflict handling are inferred by intersecting native SQLite semantics (changes() reports only the last direct statement's row changes and excludes trigger work; total_changes accumulates including trigger inserts; REPLACE counts delete+insert; IGNORE reports 0 on conflict; UPSERT reports 1) against every calibration receipt; a goal is answered only when all surviving family members agree. Exported transition/readout must tolerate a None context and None state to stay consistent with investigate.",
  "scope": "Disposable SQLite source with private stable (conflict handling, optional AFTER INSERT log trigger, channel) combination; predict channel or committed state for new sequences from receipts.",
  "source": "def make_candidates():
    cands = []
    for conflict in ["ignore", "replace", "upsert"]:
        for trig in [False, True]:
            for ch in ["changes", "total_main", "total_both"]:
                cands.append({"conflict": conflict, "trigger": trig, "channel": ch})
    return cands

def simulate(cand, actions):
    committed = {}
    main_total = 0
    other_total = 0
    main_last = 0
    txn = None
    pending = {}
    deleted = set()
    for action in actions:
        op = action.get("op")
        if op == "begin":
            if txn is None:
                txn = action.get("connection") or "main"
                pending = {}
                deleted = set()
        elif op == "commit":
            if txn is not None:
                for k in pending:
                    committed[k] = pending[k]
                for k in deleted:
                    committed.pop(k, None)
                txn = None
                pending = {}
                deleted = set()
        elif op == "rollback":
            txn = None
            pending = {}
            deleted = set()
        else:
            conn = action.get("connection") or "main"
            if txn is not None:
                conn = txn
            key = action.get("key")
            if txn is not None:
                if key in deleted:
                    cur = None
                elif key in pending:
                    cur = pending[key]
                else:
                    cur = committed.get(key)
            else:
                cur = committed.get(key)
            ch = 0
            trig = 0
            store = txn is not None
            if op == "put":
                val = action.get("value")
                if cur is None:
                    ch = 1
                    if cand["trigger"]:
                        trig = 1
                    if store:
                        pending[key] = val
                        deleted.discard(key)
                    else:
                        committed[key] = val
                elif cand["conflict"] == "ignore":
                    ch = 0
                elif cand["conflict"] == "replace":
                    ch = 2
                    if cand["trigger"]:
                        trig = 1
                    if store:
                        pending[key] = val
                        deleted.discard(key)
                    else:
                        committed[key] = val
                else:
                    ch = 1
                    if store:
                        pending[key] = val
                    else:
                        committed[key] = val
            elif op == "update":
                val = action.get("value")
                if cur is not None:
                    ch = 1
                    if store:
                        pending[key] = val
                    else:
                        committed[key] = val
            elif op == "delete":
                if cur is not None:
                    ch = 1
                    if store:
                        deleted.add(key)
                        pending.pop(key, None)
                    else:
                        committed.pop(key, None)
            if conn == "main":
                main_last = ch
                main_total = main_total + ch + trig
            else:
                other_total = other_total + ch + trig
    if cand["channel"] == "changes":
        channel = main_last
    elif cand["channel"] == "total_main":
        channel = main_total
    else:
        channel = main_total + other_total
    count = len(committed)
    total = sum(committed.values())
    return {"channel": channel, "committed_count": count, "committed_sum": total}

def filter_candidates(receipts):
    survivors = []
    for cand in make_candidates():
        ok = True
        for r in receipts:
            obs = r.get("observed")
            sim = simulate(cand, r.get("actions"))
            if sim["channel"] != obs.get("channel"):
                ok = False
            elif sim["committed_count"] != obs.get("committed_count"):
                ok = False
            elif sim["committed_sum"] != obs.get("committed_sum"):
                ok = False
            if not ok:
                break
        if ok:
            survivors.append(cand)
    return survivors

def answer(survivors, actions, goal):
    if len(survivors) == 0:
        return {"value": None, "unresolved": True}
    sims = []
    for cand in survivors:
        sims.append(simulate(cand, actions))
    if goal is None or goal not in sims[0]:
        vals = []
        for g in ["channel", "committed_count", "committed_sum"]:
            v = sims[0][g]
            for s in sims:
                if s[g] != v:
                    return {"value": None, "unresolved": True}
            vals.append(v)
        if vals[0] == vals[1] and vals[1] == vals[2]:
            return {"value": vals[0], "unresolved": False}
        return {"value": None, "unresolved": True}
    v = sims[0][goal]
    for s in sims:
        if s[goal] != v:
            return {"value": None, "unresolved": True}
    return {"value": v, "unresolved": False}

def investigate(context, acquire):
    receipts = acquire("history")
    survivors = filter_candidates(receipts)
    actions = []
    goal = None
    if context is not None:
        actions = context.get("actions") or []
        goal = context.get("goal")
    return answer(survivors, actions, goal)

def transition(state, action, context, acquire):
    if state is None:
        state = {"actions": [], "receipts": None, "survivors": None}
    state["actions"].append(action)
    return state

def readout(state, context, acquire):
    if state is None:
        state = {"actions": [], "receipts": None, "survivors": None}
    receipts = state.get("receipts")
    if receipts is None:
        receipts = acquire("history")
        state["receipts"] = receipts
    survivors = state.get("survivors")
    if survivors is None:
        survivors = filter_candidates(receipts)
        state["survivors"] = survivors
    actions = state.get("actions") or []
    goal = None
    if context is not None:
        goal = context.get("goal")
    return answer(survivors, actions, goal)
